mapper.select:
SELECT kp.*,
    s.name AS school_name,
    pkp.name AS parent_name
FROM knowledge_point kp
LEFT JOIN school s ON s.id = kp.school_id
LEFT JOIN knowledge_point pkp ON pkp.id = kp.parent_id
WHERE kp.deleted = 0

    AND kp.school_id = #{query.schoolId}


    AND kp.subject_name = #{query.subjectName}


    AND kp.name LIKE CONCAT('%', #{query.name}, '%')


    AND kp.code = #{query.code}


    AND kp.parent_id = #{query.parentId}


    AND kp.status = #{query.status}

ORDER BY kp.sort ASC, kp.create_time ASC
